reverseMap.put(')', '(');
reverseMap.put(']', '[');
reverseMap.put('}', '{');
Stack<Character> stackString = new Stack<>();

for (char current : s.toCharArray()) {
    if (reverseMap.containsKey(current)) {
        if (stackString.isEmpty() ||
            !stackString.peek().equals(reverseMap.get(current))) {
            return false;
        }
        stackString.pop();
    } else {
        stackString.push(current);
    }
}
